import java.util.Scanner;

interface Speaker {
    void speak();
}

class Cat implements Speaker {
    String name;

    Cat(String name) {
        this.name = name;
    }

    @Override
    public void speak() {
        System.out.println(name + "：喵～");
    }
}

class Robot implements Speaker {
    String name;

    Robot(String name) {
        this.name = name;
    }

    @Override
    public void speak() {
        System.out.println(name + "：{cry}");
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int rounds = sc.nextInt();
        Speaker[] crowd = { new Cat("{cat}"), new Robot("{robot}") };
        for (int r = 0; r < rounds; r++) {
            for (Speaker pet : crowd) {
                pet.speak();
            }
        }
    }
}
